import sys
import logging
from pathlib import Path

_BASE_DIR = Path(__file__).resolve().parent
_LOG_FILE = _BASE_DIR / 'casapepe_arranque.log'
if __name__ == '__main__':
    for _stream in (sys.stdout, sys.stderr):
        try:
            _stream.reconfigure(line_buffering=True, write_through=True)
        except (AttributeError, OSError, ValueError):
            pass
    _handlers = [logging.StreamHandler(sys.stderr)]
    try:
        from logging.handlers import RotatingFileHandler
        _handlers.append(RotatingFileHandler(_LOG_FILE, maxBytes=1_000_000, backupCount=3, encoding='utf-8'))
    except OSError as _error:
        print('[Casa Pepe] No se puede escribir el registro:', _error, flush=True)
    logging.basicConfig(level=logging.INFO, handlers=_handlers,
                        format='%(asctime)s %(levelname)s %(message)s', force=True)
    def _startup_exception(kind, value, tb):
        logging.critical('Fallo de Casa Pepe', exc_info=(kind, value, tb))
        if isinstance(value, ModuleNotFoundError):
            print('Instala las dependencias en Pydroid: pip install Flask tzdata', flush=True)
    sys.excepthook = _startup_exception
    print('[Casa Pepe] Iniciando aplicación...', flush=True)

