APP_VERSION = '7.6'
app = Flask(__name__)
# Detrás de un proxy inverso (Nginx, Cloudflare...) indica cuántos saltos confiar: CASAPEPE_TRUST_PROXY=1.
# Sin esto request.remote_addr sería siempre la IP del proxy y los limitadores bloquearían a todos a la vez.
_TRUST_PROXY = int(os.environ.get('CASAPEPE_TRUST_PROXY', '0') or 0) or (1 if os.environ.get('CASAPEPE_PROXY') == '1' else 0)  # CASAPEPE_PROXY=1: nombre antiguo, sigue valiendo
if _TRUST_PROXY > 0:
    app.wsgi_app = ProxyFix(app.wsgi_app, x_for=_TRUST_PROXY, x_proto=_TRUST_PROXY, x_host=_TRUST_PROXY)
_AVISO_PROXY = []


@app.before_request
def _avisar_proxy_sin_configurar():
    """Si llegan cabeceras de proxy pero CASAPEPE_TRUST_PROXY no está puesto, todos los clientes comparten IP."""
    if not _TRUST_PROXY and not _AVISO_PROXY and request.headers.get('X-Forwarded-For'):
        _AVISO_PROXY.append(True)
        app.logger.warning('Llegan cabeceras X-Forwarded-For pero CASAPEPE_TRUST_PROXY no está configurado: '
                           'los limitadores verán una sola IP y pueden bloquear a todos los clientes a la vez.')


APP_ENV = os.environ.get('CASAPEPE_ENV', 'development').strip().lower()
IS_PRODUCTION = APP_ENV == 'production'
_CONFIGURED_SECRET_KEY = os.environ.get('CASAPEPE_SECRET_KEY', '').strip()
_CONFIGURED_ADMIN_PASSWORD = os.environ.get('CASAPEPE_ADMIN_PASSWORD', '')
_CONFIGURED_PUBLIC_URL = os.environ.get('CASAPEPE_PUBLIC_URL', '').strip().rstrip('/')


def _validate_public_url(value, production=False):
    """Valida una URL canónica para no publicar enlaces SEO bajo un Host arbitrario."""
    parsed = urlsplit(value)
    valid = (parsed.scheme in ('https', 'http') and bool(parsed.netloc)
             and parsed.username is None and parsed.password is None
             and parsed.path in ('', '/') and not parsed.query and not parsed.fragment)
    if not valid or (production and parsed.scheme != 'https'):
        raise RuntimeError('CASAPEPE_PUBLIC_URL debe ser una URL absoluta válida' +
                           (' y usar HTTPS en producción.' if production else '.'))
    return value.rstrip('/')


if IS_PRODUCTION:
    missing = []
    if len(_CONFIGURED_SECRET_KEY) < 32:
        missing.append('CASAPEPE_SECRET_KEY (mínimo 32 caracteres)')
    if len(_CONFIGURED_ADMIN_PASSWORD) < 16:
        missing.append('CASAPEPE_ADMIN_PASSWORD (mínimo 16 caracteres)')
    if not _CONFIGURED_PUBLIC_URL:
        missing.append('CASAPEPE_PUBLIC_URL (URL pública HTTPS)')
    if missing:
        raise RuntimeError('Configuración de producción incompleta: ' + ', '.join(missing))

if not IS_PRODUCTION and _CONFIGURED_ADMIN_PASSWORD and len(_CONFIGURED_ADMIN_PASSWORD) < 16:
    logging.getLogger(__name__).warning('CASAPEPE_ADMIN_PASSWORD tiene menos de 16 caracteres: en producción es obligatorio.')

if _CONFIGURED_PUBLIC_URL:
    _CONFIGURED_PUBLIC_URL = _validate_public_url(_CONFIGURED_PUBLIC_URL, IS_PRODUCTION)

# En desarrollo se genera una clave temporal; en producción la clave es obligatoria y estable.
app.secret_key = _CONFIGURED_SECRET_KEY or secrets.token_hex(32)
app.config.update(
    SESSION_COOKIE_NAME='__Host-casapepe' if IS_PRODUCTION else 'session',  # __Host-: solo HTTPS, sin dominio, ruta /
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE='Lax',
    SESSION_COOKIE_SECURE=(IS_PRODUCTION or os.environ.get('CASAPEPE_COOKIE_SECURE') == '1'),
    PERMANENT_SESSION_LIFETIME=timedelta(hours=8),
    SESSION_REFRESH_EACH_REQUEST=False,
    MAX_CONTENT_LENGTH=1024 * 1024,
)


def _safe_eq(a, b):
    """Comparación en tiempo constante que admite Unicode (compare_digest con str no ASCII lanza TypeError → 500)."""
    return secrets.compare_digest(str(a).encode('utf-8'), str(b).encode('utf-8'))


def public_base_url():
    """Devuelve la URL canónica configurada; en local usa el origen de la petición."""
    return _CONFIGURED_PUBLIC_URL or request.url_root.rstrip('/')


