def init_db():
    """Crea las tablas y siembra el inventario inicial."""
    with closing(sqlite3.connect(DB_FILE, timeout=10)) as conexion:
        _crear_esquema(conexion)


def _crear_esquema(conexion):
    conexion.execute("PRAGMA journal_mode=WAL")
    conexion.execute("PRAGMA synchronous=NORMAL")
    conexion.execute("PRAGMA busy_timeout=5000")
    cursor = conexion.cursor()

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS reservas (
            id TEXT PRIMARY KEY,
            nombre TEXT NOT NULL,
            telefono TEXT NOT NULL,
            fecha TEXT NOT NULL,
            hora TEXT NOT NULL,
            pax INTEGER NOT NULL,
            zona TEXT NOT NULL DEFAULT 'Salón Central',
            created_at TEXT NOT NULL
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS pedidos (
            id TEXT PRIMARY KEY,
            cliente TEXT NOT NULL,
            detalles TEXT NOT NULL,
            total REAL NOT NULL,
            neto REAL NOT NULL,
            iva REAL NOT NULL,
            tipo_servicio TEXT NOT NULL,
            fecha_hora TEXT NOT NULL,
            estado TEXT NOT NULL DEFAULT 'En Cocina 🍳',
            camarero_id TEXT NOT NULL DEFAULT 'Terminal Web',
            created_at TEXT NOT NULL
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS inventario (
            ingrediente TEXT PRIMARY KEY,
            cantidad REAL NOT NULL,
            unidad TEXT NOT NULL,
            alerta_minima REAL NOT NULL
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS logs_seguridad (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            evento TEXT NOT NULL,
            usuario TEXT NOT NULL,
            timestamp TEXT NOT NULL,
            ip_remota TEXT NOT NULL
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS clics_web (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            elemento TEXT NOT NULL,
            destino TEXT NOT NULL,
            pagina TEXT NOT NULL,
            timestamp TEXT NOT NULL
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS encuestas_satisfaccion (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            satisfaccion INTEGER NOT NULL CHECK(satisfaccion BETWEEN 1 AND 5),
            comida INTEGER NOT NULL CHECK(comida BETWEEN 1 AND 5),
            servicio INTEGER NOT NULL CHECK(servicio BETWEEN 1 AND 5),
            limpieza INTEGER NOT NULL CHECK(limpieza BETWEEN 1 AND 5),
            recomendaria INTEGER NOT NULL CHECK(recomendaria BETWEEN 1 AND 5),
            comentario TEXT NOT NULL DEFAULT '',
            timestamp TEXT NOT NULL,
            ip_remota TEXT NOT NULL
        )
    """)

    conexion.commit()

    stock_inicial = [
        ("Caracoles de Campo", 50.0, "kg", 10.0),
        ("Alitas de Pollo Frescas", 120.0, "kg", 20.0),
        ("Oreja de Cerdo Seleccionada", 80.0, "kg", 15.0),
        ("Pollo Limpio Troceado", 100.0, "kg", 15.0),
        ("Patata Agria de la Huerta", 300.0, "kg", 50.0),
        ("Masa Artesana de Croquetas", 60.0, "kg", 10.0),
        ("Barriles Cerveza Bodega", 15.0, "uds", 3.0),
        ("Licor Vermut de Hierbas", 40.0, "litros", 8.0),
        ("Calamar Limpio", 60.0, "kg", 10.0),
        ("Gambas Peladas", 50.0, "kg", 8.0)
    ]
    # INSERT OR IGNORE: añade los ingredientes nuevos sin tocar el stock ya existente
    cursor.executemany("INSERT OR IGNORE INTO inventario VALUES (?, ?, ?, ?)", stock_inicial)
    conexion.commit()


def registrar_log_seguridad(evento, usuario="Anónimo"):
    """Inserta una traza de auditoría; un fallo de auditoría nunca debe romper la petición."""
    try:
        ip_cliente = (request.remote_addr or '?') if has_request_context() else '127.0.0.1'
        with closing(sqlite3.connect(DB_FILE, timeout=5)) as conexion:
            conexion.execute(
                "INSERT INTO logs_seguridad (evento, usuario, timestamp, ip_remota) VALUES (?, ?, ?, ?)",
                (str(evento)[:300], str(usuario)[:80], reserva_now().strftime("%Y-%m-%d %H:%M:%S"), ip_cliente)
            )
            conexion.commit()
    except sqlite3.Error:
        app.logger.warning('No se pudo registrar la traza de auditoría', exc_info=True)

