@app.after_request
def comprimir_respuesta(resp):
    """Gzip para HTML/JS/CSS/JSON: la home pesa cientos de KB y las conexiones lentas lo notan."""
    try:
        if (resp.status_code != 200 or resp.direct_passthrough or 'Content-Encoding' in resp.headers
                or 'gzip' not in request.headers.get('Accept-Encoding', '').lower()):
            return resp
        mt = (resp.mimetype or '')
        if not (mt.startswith('text/') or mt in ('application/json', 'application/javascript')):
            return resp
        data = resp.get_data()
        if len(data) < 1024:
            return resp
        if request.path in ('/carta3d.js', '/tailwind.css'):      # estáticos: se comprimen una sola vez (nivel máximo)
            gz = _GZ_CACHE.get((request.path, len(data)))
            if gz is None:
                gz = _GZ_CACHE[(request.path, len(data))] = gzip.compress(data, 9, mtime=0)
        else:
            gz = gzip.compress(data, 5, mtime=0)
        resp.set_data(gz)
        resp.headers['Content-Encoding'] = 'gzip'
        resp.headers['Content-Length'] = str(len(gz))
        resp.headers.add('Vary', 'Accept-Encoding')
    except Exception:
        pass   # la compresión nunca debe romper la respuesta
    return resp


