_RL = {}
_RL_LOCK = Lock()


def limite_ok(clave, maximo, ventana=60):
    """Limitador en memoria por IP+ámbito (ventana deslizante simple). Protege la base de datos del spam."""
    ahora = time.monotonic()
    clave = (clave, request.remote_addr or '?')
    with _RL_LOCK:           # el servidor es multihilo (waitress/Flask threaded)
        marcas = [t for t in _RL.get(clave, ()) if ahora - t < ventana]
        if len(marcas) >= maximo:
            _RL[clave] = marcas
            return False
        marcas.append(ahora)
        _RL[clave] = marcas
        if len(_RL) > 5000:      # evita crecimiento indefinido
            for k in [k for k, v in _RL.items() if not v or ahora - v[-1] > ventana]:
                _RL.pop(k, None)
        return True


TEL_RE = re.compile(r'^\+?[0-9 ]{9,16}$')


@app.route('/encuesta-satisfaccion', methods=['POST'])
def encuesta_satisfaccion():
    """Guarda una valoración anónima de satisfacción del cliente."""
    if request.form.get('web'):           # trampa anti-bots
        return redirect(url_for('home') + '#satisfaccion')
    if not limite_ok('encuesta', 5, 600):
        flash("Has enviado varias valoraciones seguidas. Inténtalo de nuevo en unos minutos.", "error")
        return redirect(url_for('home') + '#satisfaccion')
    campos = ['satisfaccion', 'comida', 'servicio', 'limpieza', 'recomendaria']
    valores = {}
    try:
        for campo in campos:
            valor = int(request.form.get(campo, '0'))
            if valor < 1 or valor > 5:
                raise ValueError
            valores[campo] = valor
    except (TypeError, ValueError):
        flash("Por favor, completa todas las valoraciones.", "error")
        return redirect(url_for('home') + '#satisfaccion')

    comentario = request.form.get('comentario', '').strip()[:500]
    now_str = reserva_now().strftime("%Y-%m-%d %H:%M:%S")

    try:
        with closing(sqlite3.connect(DB_FILE, timeout=10)) as conexion, conexion:
            conexion.execute("""
                INSERT INTO encuestas_satisfaccion
                (satisfaccion, comida, servicio, limpieza, recomendaria, comentario, timestamp, ip_remota)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """, (valores['satisfaccion'], valores['comida'], valores['servicio'],
                  valores['limpieza'], valores['recomendaria'], comentario, now_str, 'anonimizada'))
    except sqlite3.Error:
        app.logger.exception('No se pudo guardar la encuesta')
        flash("No hemos podido guardar tu valoración. Inténtalo de nuevo en unos segundos.", "error")
        return redirect(url_for('home') + '#satisfaccion')

    flash("Gracias por tu valoración. Tu opinión nos ayuda a mejorar Casa Pepe.", "success")
    return redirect(url_for('home') + '#satisfaccion')



