def _csv_safe(value):
    """Neutraliza fórmulas al abrir exportaciones CSV en Excel/LibreOffice."""
    value = '' if value is None else str(value)
    if re.fullmatch(r'\+\d{9,15}', value):   # teléfono internacional: no es una fórmula
        return value
    if value.lstrip().startswith(('=', '+', '-', '@', '\t', '\r')):
        return "'" + value
    return value


@app.route('/panel-clics/export.csv')
def exportar_clics_csv():
    """Exportación privada de analítica; requiere una sesión de administrador."""
    if not session.get('panel_clics_ok'):
        abort(403)
    with closing(sqlite3.connect(DB_FILE, timeout=10)) as conexion:
        filas = conexion.execute(
            'SELECT timestamp, elemento, destino, pagina FROM clics_web ORDER BY id DESC'
        ).fetchall()
    salida = io.StringIO(newline='')
    writer = csv.writer(salida)
    writer.writerow(['Fecha y hora', 'Elemento', 'Destino / ID', 'Página'])
    writer.writerows([_csv_safe(v) for v in fila] for fila in filas)
    respuesta = Response('\ufeff' + salida.getvalue(), mimetype='text/csv; charset=utf-8')
    respuesta.headers['Content-Disposition'] = 'attachment; filename="casa-pepe-clics.csv"'
    respuesta.headers['Cache-Control'] = 'no-store'
    return respuesta

@app.route('/api/registrar-clic', methods=['POST'])
def registrar_clic_web():
    """Guarda eventos de clic sin recoger IP, cookies ni datos personales."""
    if not limite_ok('clic', 120, 60):
        return ('', 204)
    datos = request.get_json(silent=True)
    if not isinstance(datos, dict):
        return ('', 204)  # La analítica es opcional; nunca debe romper la web pública.
    elemento = str(datos.get('elemento', 'elemento')).replace('\x00', '')[:100].strip() or 'elemento'
    destino = str(datos.get('destino', '')).replace('\x00', '')[:180].strip()
    pagina = str(datos.get('pagina', '/')).replace('\x00', '')[:180].strip() or '/'
    if not pagina.startswith('/') or pagina.startswith('//'):
        pagina = '/'
    try:
        with closing(sqlite3.connect(DB_FILE, timeout=5)) as conexion, conexion:
            conexion.execute(
                'INSERT INTO clics_web (elemento, destino, pagina, timestamp) VALUES (?, ?, ?, ?)',
                (elemento, destino, pagina, reserva_now().strftime('%Y-%m-%d %H:%M:%S'))
            )
        return ('', 204)
    except sqlite3.Error:
        return ('', 204)  # La analítica nunca debe ralentizar ni romper la web pública.


@app.route('/panel-clics', methods=['GET', 'POST'])
def panel_clics():
    """Panel privado de clics. Se deniega el acceso si falta configurar contraseña."""
    password_configurada = os.environ.get('CASAPEPE_ADMIN_PASSWORD', '')
    if not password_configurada:
        return render_template_string('''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel privado</title><body style="font-family:system-ui;max-width:680px;margin:12vh auto;padding:24px;background:#111;color:#eee"><h1>Panel de clics no configurado</h1><p>Por seguridad, configura la variable de entorno <code>CASAPEPE_ADMIN_PASSWORD</code> en el alojamiento y reinicia el servicio.</p><p>El panel no es público: no se puede iniciar sesión hasta que exista esa contraseña.</p></body></html>'''), 503

    if request.method == 'POST':
        if not _safe_eq(request.form.get('csrf', ''), reserva_csrf()):
            abort(400)
        accion = request.form.get('accion', 'login')
        if accion == 'salir':
            for _k in ('admin_ok', 'panel_clics_ok', 'reservas_admin', 'satisfaccion_admin'):
                session.pop(_k, None)
            return redirect(url_for('panel_clics'))
        if not limite_ok('login-clics', 8, 600):
            return 'Demasiados intentos. Espera 10 minutos.', 429
        if _safe_eq(request.form.get('password', ''), password_configurada):
            session.clear()
            session['admin_ok'] = True
            session['panel_clics_ok'] = True
            session['reservas_admin'] = True
            session['satisfaccion_admin'] = True
            session.permanent = True
            registrar_log_seguridad('Acceso al panel privado de clics', 'Administrador')
            return redirect(url_for('panel_clics'))
        registrar_log_seguridad('Intento fallido de acceso al panel de clics', 'Desconocido')
        flash('Contraseña incorrecta.', 'error')

    if not session.get('panel_clics_ok'):
        return render_template_string('''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acceso privado · Casa Pepe</title><style>body{font-family:system-ui;background:#0c0a09;color:#f5f5f4;display:grid;place-items:center;min-height:90vh;margin:0;padding:20px}.box{width:min(420px,100%);padding:28px;border:1px solid #66501b;border-radius:18px;background:#1c1917}input,button{box-sizing:border-box;width:100%;padding:13px;margin-top:12px;border-radius:9px}input{background:#0c0a09;border:1px solid #57534e;color:white}button{background:#b88918;color:#111;font-weight:800;border:0;cursor:pointer}.muted{color:#a8a29e;font-size:14px}</style></head><body><main class="box"><h1>Panel privado de clics</h1><p class="muted">Acceso exclusivo para administración. Estos datos no aparecen en la web pública.</p>{% with messages = get_flashed_messages() %}{% for message in messages %}<p>{{ message }}</p>{% endfor %}{% endwith %}<form method="post"><input type="hidden" name="csrf" value="{{ reserva_csrf() }}"><input type="password" name="password" placeholder="Contraseña de administrador" autocomplete="current-password" required><button type="submit">Entrar al panel</button></form></main></body></html>''')

