def reserva_notificar_admin(asunto, contenido):
    """Notificación SMTP opcional. Un fallo de correo nunca invalida una reserva ya guardada."""
    host = os.environ.get('CASAPEPE_SMTP_HOST', '').strip()
    destino = os.environ.get('CASAPEPE_NOTIFICACION_EMAIL', '').strip()
    remitente = os.environ.get('CASAPEPE_SMTP_FROM', os.environ.get('CASAPEPE_SMTP_USER', '')).strip()
    if not host or not destino or not remitente:
        return False  # la función es opcional hasta configurar el correo transaccional
    try:
        puerto = int(os.environ.get('CASAPEPE_SMTP_PORT', '587'))
        usuario = os.environ.get('CASAPEPE_SMTP_USER', '').strip()
        clave = os.environ.get('CASAPEPE_SMTP_PASSWORD', '')
        mensaje = EmailMessage()
        mensaje['Subject'] = asunto[:180]
        mensaje['From'] = remitente
        mensaje['To'] = destino
        mensaje.set_content(contenido[:8000])
        contexto = ssl.create_default_context()
        if os.environ.get('CASAPEPE_SMTP_USE_SSL') == '1' or puerto == 465:
            with smtplib.SMTP_SSL(host, puerto, timeout=4, context=contexto) as servidor:
                if usuario and clave:
                    servidor.login(usuario, clave)
                servidor.send_message(mensaje)
        else:
            with smtplib.SMTP(host, puerto, timeout=4) as servidor:
                servidor.ehlo()
                servidor.starttls(context=contexto)
                servidor.ehlo()
                if usuario and clave:
                    servidor.login(usuario, clave)
                servidor.send_message(mensaje)
        return True
    except (smtplib.SMTPException, OSError, ValueError):
        app.logger.warning('No se pudo enviar una notificación SMTP de Casa Pepe', exc_info=True)
        return False
def reserva_db():
    db = sqlite3.connect(DB_FILE, timeout=10)
    db.row_factory = sqlite3.Row
    db.execute('PRAGMA busy_timeout=10000')
    db.execute('PRAGMA foreign_keys=ON')
    db.execute('PRAGMA synchronous=NORMAL')
    db.execute('PRAGMA trusted_schema=OFF')
    return db
def init_reservas_pro():
    with closing(reserva_db()) as db:
        db.execute('CREATE TABLE IF NOT EXISTS reservas_meta (reserva_id TEXT PRIMARY KEY REFERENCES reservas(id), token TEXT UNIQUE NOT NULL, submission TEXT UNIQUE, estado TEXT NOT NULL DEFAULT "Confirmada", cancelada_at TEXT, privacidad_at TEXT)')
        db.execute('CREATE INDEX IF NOT EXISTS idx_reservas_fecha ON reservas(fecha)')
        db.execute('CREATE INDEX IF NOT EXISTS idx_reservas_fecha_hora ON reservas(fecha,hora)')
        db.execute('CREATE INDEX IF NOT EXISTS idx_reservas_tel ON reservas(telefono,fecha)')
        db.execute('CREATE INDEX IF NOT EXISTS idx_clics_pagina ON clics_web(pagina)')
        db.execute('CREATE INDEX IF NOT EXISTS idx_clics_elemento ON clics_web(elemento)')
        db.execute('CREATE INDEX IF NOT EXISTS idx_logs_ts ON logs_seguridad(timestamp)')
        db.execute('DELETE FROM logs_seguridad WHERE timestamp < ?', ((reserva_now() - timedelta(days=365)).strftime('%Y-%m-%d %H:%M:%S'),))  # retención RGPD: guardan IP
        # purga: los clics anónimos de más de 180 días no aportan y solo engordan la base de datos
        db.execute('DELETE FROM clics_web WHERE timestamp < ?', ((reserva_now() - timedelta(days=180)).strftime('%Y-%m-%d %H:%M:%S'),))
        db.execute('CREATE TABLE IF NOT EXISTS reservas_rate (ip TEXT PRIMARY KEY, inicio INTEGER NOT NULL, intentos INTEGER NOT NULL)')
        if RES_RETENCION_DIAS > 0:   # minimización de datos: se borran nombre y teléfono de reservas antiguas
            limite = (reserva_now().date() - timedelta(days=RES_RETENCION_DIAS)).isoformat()
            db.execute('DELETE FROM reservas_meta WHERE reserva_id IN (SELECT id FROM reservas WHERE fecha < ?)', (limite,))
            db.execute('DELETE FROM reservas WHERE fecha < ?', (limite,))
        db.commit()
        try:
            db.execute('PRAGMA wal_checkpoint(TRUNCATE)')   # el archivo -wal no crece indefinidamente
        except sqlite3.Error:
            pass
def reserva_csrf():
    if 'res_csrf' not in session:session['res_csrf']=secrets.token_urlsafe(32)
    return session['res_csrf']
def reserva_submission():
    if 'res_submission' not in session:session['res_submission']=secrets.token_urlsafe(24)
    return session['res_submission']
def reserva_horas():return [f'{m//60:02d}:{m%60:02d}' for lo,hi in ((750,990),(1170,1410)) for m in range(lo,hi+1,15)]
@app.context_processor
def reserva_context():
    return dict(reserva_csrf=reserva_csrf,reserva_submission=reserva_submission,reserva_hoy=lambda:reserva_now().date().isoformat(),reserva_max_fecha=lambda:(reserva_now().date()+timedelta(days=90)).isoformat(),reserva_horas=reserva_horas,reserva_zonas=RES_ZONAS)
def reserva_check_csrf():return bool(session.get('res_csrf')) and _safe_eq(request.form.get('csrf',''),session['res_csrf'])
def reserva_fecha_pax(fecha,pax):
    try:dia=date.fromisoformat(fecha);personas=int(pax)
    except (ValueError,TypeError):raise ValueError('Revisa la fecha y el número de personas.')
    if not reserva_now().date()<=dia<=reserva_now().date()+timedelta(days=90):raise ValueError('Elige una fecha desde hoy hasta los próximos 90 días.')
    if not 1<=personas<=20:raise ValueError('Las reservas online admiten de 1 a 20 personas.')
    return dia,personas
def reserva_cargar(db,fecha):
    rows=db.execute('SELECT r.hora,r.pax FROM reservas r LEFT JOIN reservas_meta m ON m.reserva_id=r.id WHERE r.fecha=? AND COALESCE(m.estado,"Confirmada")="Confirmada"',(fecha,)).fetchall()
    return [(datetime.fromisoformat(fecha+'T'+r['hora']),r['pax']) for r in rows]
def reserva_cabe(db,fecha,hora,pax,starts=None):
    target=datetime.fromisoformat(fecha+'T'+hora)
    if starts is None:starts=reserva_cargar(db,fecha)
    finish=target+timedelta(minutes=RES_DURACION)
    for instant in [target]+[t for t,_ in starts if target<=t<finish]:
        if sum(p for t,p in starts if t<=instant<t+timedelta(minutes=RES_DURACION))+pax>RES_CAPACIDAD:return False
    return True
def reserva_hora_valida(dia,hora):return hora in reserva_horas() and datetime.fromisoformat(dia.isoformat()+'T'+hora).replace(tzinfo=RES_TZ)>=reserva_now()+timedelta(minutes=RES_ANTELACION)
@app.route('/api/reservas/disponibilidad')
def reserva_disponibilidad():
    # Evita que un cliente automatizado haga consultas ilimitadas a SQLite.
    if not limite_ok('reserva-disponibilidad', 90, 60):
        response = jsonify(error='Demasiadas consultas. Espera un minuto y vuelve a intentarlo.')
        response.status_code = 429
        response.headers['Retry-After'] = '60'
        response.headers['Cache-Control'] = 'no-store'
        return response
    try:
        dia,pax=reserva_fecha_pax(request.args.get('fecha',''),request.args.get('pax',''))
        with closing(reserva_db()) as db:
            ocupadas=reserva_cargar(db,dia.isoformat());horas=[dict(hora=h,disponible=reserva_cabe(db,dia.isoformat(),h,pax,ocupadas)) for h in reserva_horas() if reserva_hora_valida(dia,h)]
        response=jsonify(horas=horas)
    except ValueError as exc:response=jsonify(error=str(exc));response.status_code=400
    response.headers['Cache-Control']='no-store';return response
def reserva_rate_ok(db,ambito='res'):
    now=int(reserva_now().timestamp());ip=ambito+':'+(request.remote_addr or 'unknown');row=db.execute('SELECT * FROM reservas_rate WHERE ip=?',(ip,)).fetchone()
    if row and now-row['inicio']<600:db.execute('UPDATE reservas_rate SET intentos=intentos+1 WHERE ip=?',(ip,));return row['intentos']<12
    db.execute('INSERT OR REPLACE INTO reservas_rate VALUES (?,?,1)',(ip,now));db.execute('DELETE FROM reservas_rate WHERE inicio<?',(now-86400,));return True
@app.route('/reservar', methods=['POST'])
def reservar():
    if not reserva_check_csrf():return 'La sesión ha caducado. Recarga la página antes de reservar.',400
    if request.form.get('web'):abort(400)
    draft={k:request.form.get(k,'')[:80] for k in ('nombre','telefono','pax','fecha','hora','zona')};session['reserva_draft']=draft;destino=url_for('home')+'#reservas'
    try:
        submission=request.form.get('submission','')
        if not submission or not _safe_eq(submission,session.get('res_submission','')):raise ValueError('Recarga la página antes de enviar otra reserva.')
        nombre=' '.join(draft['nombre'].split());telefono=re.sub(r'[\s().-]','',draft['telefono']);dia,pax=reserva_fecha_pax(draft['fecha'],draft['pax']);hora=draft['hora'];zona=draft['zona']
        if not 2<=len(nombre)<=60:raise ValueError('Indica un nombre de entre 2 y 60 caracteres.')
        if not re.fullmatch(r'\+?[0-9]{9,15}',telefono):raise ValueError('Revisa tu teléfono; puedes incluir el prefijo internacional.')
        if zona not in RES_ZONAS:raise ValueError('Selecciona una de las zonas disponibles.')
        if not reserva_hora_valida(dia,hora):raise ValueError(f'Elige un horario válido con al menos {RES_ANTELACION} minutos de antelación.')
        if request.form.get('privacidad')!='1':raise ValueError('Lee la información sobre el uso de datos antes de confirmar.')
        with closing(reserva_db()) as db:
            db.execute('BEGIN IMMEDIATE');existing=db.execute('SELECT token FROM reservas_meta WHERE submission=?',(submission,)).fetchone()
            if existing:db.rollback();return redirect(url_for('reserva_detalle',token=existing['token']))
            if not reserva_rate_ok(db):db.commit();raise ValueError('Demasiados intentos. Espera 10 minutos o llámanos.')
            if not reserva_cabe(db,dia.isoformat(),hora,pax):db.commit();raise ValueError('Ese horario acaba de completarse. Elige otra hora; conservamos tus datos.')
            if db.execute('SELECT m.token FROM reservas r JOIN reservas_meta m ON m.reserva_id=r.id WHERE r.telefono=? AND r.fecha=? AND r.hora=? AND m.estado="Confirmada"',(telefono,dia.isoformat(),hora)).fetchone():db.commit();raise ValueError('Ya existe una reserva con ese teléfono a esa hora. Usa el enlace de tu confirmación o llámanos.')
            codigo='R-'+secrets.token_hex(6).upper();token=secrets.token_urlsafe(32);stamp=reserva_now().isoformat()
            db.execute('INSERT INTO reservas (id,nombre,telefono,fecha,hora,pax,zona,created_at) VALUES (?,?,?,?,?,?,?,?)',(codigo,nombre,telefono,dia.isoformat(),hora,pax,zona,stamp))
            db.execute('INSERT INTO reservas_meta (reserva_id,token,submission,privacidad_at) VALUES (?,?,?,?)',(codigo,token,submission,stamp));db.commit()
        session.pop('reserva_draft',None);session.pop('reserva_error',None);session.pop('res_submission',None);registrar_log_seguridad(f'Reserva web {codigo}','Web');reserva_notificar_admin('Nueva reserva en Casa Pepe · '+codigo, f'Nueva reserva confirmada\nCódigo: {codigo}\nNombre: {nombre}\nTeléfono: {telefono}\nFecha: {dia.isoformat()}\nHora: {hora}\nPersonas: {pax}\nZona: {zona}');return redirect(url_for('reserva_detalle',token=token))
    except ValueError as exc:session['reserva_error']=str(exc);return redirect(destino)
    except sqlite3.Error:app.logger.exception('Error SQLite al reservar');session['reserva_error']='No pudimos guardar la reserva. Tus datos siguen aquí; inténtalo de nuevo en unos segundos.';return redirect(destino)
RES_PAGE='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Tu reserva · Casa Pepe</title><style>body{background:#0c0a09;color:#eee;font:16px system-ui;margin:0;padding:20px}main{max-width:640px;margin:40px auto;padding:28px;background:#1c1917;border:1px solid #66501b;border-radius:24px}a{color:#e5c15b}button,.btn{display:inline-block;padding:14px;border-radius:12px;background:#d4af37;color:#111;border:0;font-weight:700;margin:8px 0;text-decoration:none}dt{color:#a8a29e;margin-top:16px}dd{margin:5px 0}input{padding:12px;font-size:16px;width:90%}small{color:#a8a29e}</style></head><body><main>{{ content|safe }}</main></body></html>'''
def reserva_record(token):
    if not re.fullmatch(r'[A-Za-z0-9_-]{43}',token):abort(404)
    with closing(reserva_db()) as db:row=db.execute('SELECT r.*,m.estado,m.token FROM reservas r JOIN reservas_meta m ON r.id=m.reserva_id WHERE m.token=?',(token,)).fetchone()
    if not row:abort(404)
    return row
@app.route('/reserva/<token>',methods=['GET','POST'])
def reserva_detalle(token):
    row=reserva_record(token)
    if request.method=='POST':
        if not reserva_check_csrf():abort(400)
        if request.form.get('accion')!='cancelar' or request.form.get('confirmar')!='si':abort(400)
        cita=datetime.fromisoformat(row['fecha']+'T'+row['hora']).replace(tzinfo=RES_TZ)
        if cita<=reserva_now():return 'Esta reserva ya ha comenzado. Contacta con el restaurante.',409
        with closing(reserva_db()) as db:cambiada=db.execute('UPDATE reservas_meta SET estado="Cancelada", cancelada_at=? WHERE token=? AND estado="Confirmada"',(reserva_now().isoformat(),token)).rowcount;db.commit()
        if not cambiada:return redirect(url_for('reserva_detalle',token=token))
        registrar_log_seguridad('Reserva cancelada por el cliente '+row['id'],'Cliente')
        reserva_notificar_admin('Reserva cancelada en Casa Pepe · '+row['id'], f'Reserva cancelada por el cliente\nCódigo: {row["id"]}\nNombre: {row["nombre"]}\nTeléfono: {row["telefono"]}\nFecha: {row["fecha"]}\nHora: {row["hora"]}\nPersonas: {row["pax"]}')
        return redirect(url_for('reserva_detalle',token=token))
    content=render_template_string('''<h1>{{ 'Reserva cancelada' if r.estado == 'Cancelada' else ('Reserva finalizada' if r.estado in ('Atendida','No presentada') else '¡Tu reserva está confirmada!') }}</h1><p>{{ r.nombre }}, {{ 'hemos liberado las plazas.' if r.estado == 'Cancelada' else ('gracias por venir a Casa Pepe.' if r.estado == 'Atendida' else ('La reserva figura como no presentada. Contacta con el restaurante si crees que es un error.' if r.estado == 'No presentada' else 'te esperamos en Casa Pepe.')) }}</p><dl><dt>Código</dt><dd>{{ r.id }}</dd><dt>Fecha y hora · Madrid</dt><dd>{{ r.fecha }} · {{ r.hora }}</dd><dt>Personas</dt><dd>{{ r.pax }}</dd><dt>Preferencia de zona</dt><dd>{{ r.zona }} (sujeta a disponibilidad)</dd><dt>Dirección</dt><dd>{{ bar.direccion }}</dd></dl><a class="btn" href="{{ url_for('reserva_calendario',token=r.token) }}">Añadir al calendario</a><p><a href="https://www.google.com/maps/search/?api=1&query={{ bar.direccion|urlencode }}" rel="noopener noreferrer" target="_blank">Cómo llegar</a> · <a href="tel:{{ bar.telefono|replace(' ','') }}">Llamar al restaurante</a></p><p>Guarda este enlace privado. Quien lo tenga podrá consultar y cancelar tu reserva. No lo compartas públicamente.</p><button type="button" onclick="window.print()">Imprimir confirmación</button>{% if r.estado == 'Confirmada' %}<details><summary>Cancelar reserva</summary><form method="post"><input type="hidden" name="csrf" value="{{ reserva_csrf() }}"><input type="hidden" name="accion" value="cancelar"><label><input type="checkbox" name="confirmar" value="si" required style="width:auto"> Confirmo que quiero cancelar y liberar las plazas.</label><br><button type="submit">Cancelar mi reserva</button></form></details>{% endif %}<p><a href="/">Volver a Casa Pepe</a></p>''',r=row,bar=INFO_BAR)
    return render_template_string(RES_PAGE,content=content)
@app.route('/reserva/<token>/calendario.ics')
def reserva_calendario(token):
    row=reserva_record(token)
    if row['estado']!='Confirmada':abort(410)
    inicio=datetime.fromisoformat(row['fecha']+'T'+row['hora']).replace(tzinfo=RES_TZ)
    def utc(dt):return dt.astimezone(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    def esc(text):return text.replace('\\','\\\\').replace('\n','\\n').replace(',','\\,').replace(';','\\;')
    fields=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Casa Pepe//Reservas//ES','BEGIN:VEVENT','UID:'+row['id']+'@casapepe','DTSTAMP:'+utc(reserva_now()),'DTSTART:'+utc(inicio),'DTEND:'+utc(inicio+timedelta(minutes=RES_DURACION)),'SUMMARY:Reserva en Casa Pepe','LOCATION:'+esc(INFO_BAR['direccion']),'DESCRIPTION:'+esc('Código '+row['id']+' · '+str(row['pax'])+' personas'),'END:VEVENT','END:VCALENDAR']
    folded=[]
    for field in fields:
        part='';size=0
        for char in field:
            length=len(char.encode('utf-8'))
            if size+length>73:folded.append(part);part=' ';size=1
            part+=char;size+=length
        folded.append(part)
    response=Response('\r\n'.join(folded)+'\r\n',mimetype='text/calendar');response.headers['Content-Disposition']='attachment; filename="reserva-casapepe.ics"';return response
@app.after_request
def reserva_private_headers(response):
    if request.path.startswith(('/reserva/','/panel-reservas','/panel-clics','/panel-admin','/panel-satisfaccion','/api/reservas')):
        response.headers['Cache-Control']='no-store, max-age=0'
        response.headers['Pragma']='no-cache'
        response.headers['Referrer-Policy']='no-referrer'
        response.headers['X-Robots-Tag']='noindex, nofollow'
    return response
@app.route('/privacidad-reservas')
def reserva_privacidad():
    content=render_template_string('''<h1>Información sobre reservas</h1><p>Los datos del formulario se guardan para gestionar tu reserva y contactar contigo si es necesario. No se usan en este módulo para publicidad.</p><p>El enlace privado permite consultar o cancelar la reserva. Conserva ese enlace de forma segura.</p><p>Contacto: {{ bar.telefono }} · {{ bar.direccion }}.</p><p>Antes de publicar comercialmente, completa la política de privacidad con identidad legal, base jurídica, conservación, derechos, proveedores y transferencias.</p><a href="/#reservas">Volver a reservar</a>''',bar=INFO_BAR)
    return render_template_string(RES_PAGE,content=content)

@app.route('/panel-reservas/export.csv')
def exportar_reservas_csv():
    """Descarga privada de reservas; admite un día concreto o todas las reservas."""
    if not _admin_autenticado():
        abort(403)
    fecha = request.args.get('fecha', '').strip()
    if fecha:
        try:
            date.fromisoformat(fecha)
        except ValueError:
            abort(400)
    consulta = """SELECT r.id, r.nombre, r.telefono, r.fecha, r.hora, r.pax,
                         r.zona, COALESCE(m.estado, 'Confirmada') AS estado,
                         r.created_at
                  FROM reservas r
                  LEFT JOIN reservas_meta m ON m.reserva_id = r.id"""
    parametros = ()
    if fecha:
        consulta += ' WHERE r.fecha = ?'
        parametros = (fecha,)
    consulta += ' ORDER BY r.fecha, r.hora'
    with closing(reserva_db()) as db:
        filas = db.execute(consulta, parametros).fetchall()
    salida = io.StringIO(newline='')
    writer = csv.writer(salida)
    writer.writerow(['Código', 'Nombre', 'Teléfono', 'Fecha', 'Hora', 'Personas',
                     'Zona preferida', 'Estado', 'Creada'])
    for fila in filas:
        writer.writerow([_csv_safe(fila[c]) for c in
                         ('id', 'nombre', 'telefono', 'fecha', 'hora', 'pax',
                          'zona', 'estado', 'created_at')])
    registrar_log_seguridad('Exportación CSV de reservas', 'Administrador')
    nombre = f"casa-pepe-reservas-{fecha}.csv" if fecha else "casa-pepe-reservas.csv"
    respuesta = Response('\ufeff' + salida.getvalue(), mimetype='text/csv; charset=utf-8')
    respuesta.headers['Content-Disposition'] = f'attachment; filename="{nombre}"'
    respuesta.headers['Cache-Control'] = 'no-store'
    respuesta.headers['X-Robots-Tag'] = 'noindex, nofollow'
    return respuesta

@app.route('/panel-reservas',methods=['GET','POST'])
def panel_reservas():
    password=os.environ.get('CASAPEPE_ADMIN_PASSWORD','')
    if not password:return 'Configura CASAPEPE_ADMIN_PASSWORD para activar el panel privado.',503
    error=''
    if request.method=='POST':
        if not reserva_check_csrf():abort(400)
        with closing(reserva_db()) as db:db.execute('BEGIN IMMEDIATE');allowed=request.form.get('accion')=='salir' or reserva_rate_ok(db,'panel');db.commit()
        if not allowed:return 'Demasiados intentos. Espera 10 minutos.',429
        if request.form.get('accion')=='salir':
            for _k in ('admin_ok', 'panel_clics_ok', 'reservas_admin', 'satisfaccion_admin'):
                session.pop(_k, None)
        elif _safe_eq(request.form.get('password',''),password):
            session.clear();session['admin_ok']=True;session['panel_clics_ok']=True;session['reservas_admin']=True;session['satisfaccion_admin']=True;session.permanent=True;registrar_log_seguridad('Acceso al panel de reservas','Administrador')
        else:registrar_log_seguridad('Intento fallido de acceso al panel de reservas','Desconocido');error='Contraseña incorrecta.'
    if not session.get('reservas_admin'):
        content=render_template_string('''<h1>Panel privado de reservas</h1><p>{{ error }}</p><form method="post"><input type="hidden" name="csrf" value="{{ reserva_csrf() }}"><label>Contraseña<input type="password" name="password" autocomplete="current-password" required></label><button>Entrar</button></form>''',error=error)
    else:
        fecha=request.args.get('fecha',reserva_now().date().isoformat())
        try:date.fromisoformat(fecha)
        except ValueError:abort(400)
        with closing(reserva_db()) as db:rows=db.execute('SELECT r.*,COALESCE(m.estado,"Confirmada") AS estado FROM reservas r LEFT JOIN reservas_meta m ON m.reserva_id=r.id WHERE fecha=? ORDER BY hora',(fecha,)).fetchall()
        content=render_template_string('''<h1>Agenda de reservas</h1>{% with messages = get_flashed_messages(with_categories=true) %}{% for category, message in messages %}<p role="status" style="padding:10px;border:1px solid #66501b;border-radius:8px">{{ message }}</p>{% endfor %}{% endwith %}<form method="get"><label>Fecha<input type="date" name="fecha" value="{{ fecha }}"></label><button>Consultar</button> <a style="color:#e5c15b;margin-left:10px" href="{{ url_for('exportar_reservas_csv', fecha=fecha) }}">Exportar este día a CSV</a> <a style="color:#e5c15b;margin-left:10px" href="{{ url_for('exportar_reservas_csv') }}">Exportar todas</a></form><p>{{ rows|length }} reservas · {{ pax }} comensales confirmados</p>{% for r in rows %}<article style="border-top:1px solid #57534e;padding:16px 0"><h2>{{ r.hora }} · {{ r.pax }} personas</h2><p>{{ r.nombre }} · <a href="tel:{{ r.telefono }}" style="color:#e5c15b">{{ r.telefono }}</a></p><p>{{ r.zona }} · <strong>{{ r.estado }}</strong> · {{ r.id }}</p><form method="post" action="{{ url_for('panel_reservas_estado') }}" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><input type="hidden" name="csrf" value="{{ reserva_csrf() }}"><input type="hidden" name="reserva_id" value="{{ r.id }}"><input type="hidden" name="fecha" value="{{ fecha }}"><label for="estado-{{ r.id }}">Estado</label><select id="estado-{{ r.id }}" name="estado" style="padding:9px;border-radius:8px;background:#0c0a09;color:#eee;border:1px solid #57534e"><option value="Confirmada" {% if r.estado == 'Confirmada' %}selected{% endif %}>Confirmada</option><option value="Cancelada" {% if r.estado == 'Cancelada' %}selected{% endif %}>Cancelada</option><option value="Atendida" {% if r.estado == 'Atendida' %}selected{% endif %}>Atendida</option><option value="No presentada" {% if r.estado == 'No presentada' %}selected{% endif %}>No presentada</option></select><button type="submit">Guardar estado</button></form></article>{% else %}<p>No hay reservas para este día.</p>{% endfor %}<form method="post"><input type="hidden" name="csrf" value="{{ reserva_csrf() }}"><input type="hidden" name="accion" value="salir"><button>Cerrar sesión</button></form>''',rows=rows,fecha=fecha,pax=sum(r['pax'] for r in rows if r['estado']=='Confirmada'))
    return render_template_string(RES_PAGE,content=content)

