@app.errorhandler(400)
def error_400(_e):
    return _pagina_error('Solicitud no válida', 'No hemos podido procesar el envío. Recarga la página e inténtalo de nuevo.', 400)


@app.errorhandler(403)
def error_403(_e):
    return _pagina_error('Acceso denegado', 'No tienes permiso para ver esta página.', 403)


@app.errorhandler(405)
def error_405(_e):
    return _pagina_error('Método no permitido', 'Esa dirección no admite este tipo de petición.', 405)


@app.errorhandler(413)
def error_413(_e):
    # El límite de cuerpo de 1 MiB evita que formularios enormes consuman memoria.
    return _pagina_error('Solicitud demasiado grande', 'El envío supera el tamaño permitido. Reduce los datos e inténtalo de nuevo.', 413)


@app.errorhandler(500)
def error_500(_e):
    app.logger.exception('Error interno')
    return _pagina_error('Algo ha fallado', 'Ha ocurrido un error por nuestra parte. Inténtalo de nuevo en unos segundos o llámanos.', 500)


def _pagina_error(titulo, texto, codigo):
    if request.path.startswith('/api/'):
        return jsonify(error=titulo), codigo
    html = render_template_string(RES_PAGE, content=render_template_string(
        '<h1>{{ t }}</h1><p>{{ x }}</p><p><a href="{{ url_for(\'home\') }}">← Volver a Casa Pepe</a> · {{ tel }}</p>',
        t=titulo, x=texto, tel=INFO_BAR['telefono']))
    return html, codigo


@app.route('/healthz')
def healthz():
    """Liveness probe: indica que Flask responde. Usa /readyz para comprobar SQLite."""
    return Response('ok', mimetype='text/plain', headers={'Cache-Control': 'no-store'})


def _autocomprobacion():
    """Comprueba que la web responde (solo lectura). Uso: python casapepe_final.py --check"""
    cliente = app.test_client()
    pruebas = [('/', 200), ('/healthz', 200), ('/readyz', 200), ('/carta3d.js', 200), ('/robots.txt', 200),
               ('/sitemap.xml', 200), ('/privacidad-reservas', 200), ('/foto/p1/0.jpg', 200), ('/no-existe', 404)]
    fallos = 0
    for ruta, esperado in pruebas:
        codigo = cliente.get(ruta).status_code
        fallos += codigo != esperado
        print(('OK    ' if codigo == esperado else 'FALLO ') + ruta + ' → ' + str(codigo))
    print('Versión %s · entorno %s · base de datos %s' % (APP_VERSION, APP_ENV, DB_FILE))
    print('Contraseña de administración: ' + ('configurada' if os.environ.get('CASAPEPE_ADMIN_PASSWORD') else 'SIN CONFIGURAR (los paneles no funcionarán)'))
    print('CSS de Tailwind precompilado: ' + ('sí' if _TW_CSS else 'no (se usa la CDN)'))
    return 1 if fallos else 0


if __name__ == "__main__":
    if '--check' in sys.argv:
        sys.exit(_autocomprobacion())
    _puerto = int(os.environ.get('PORT', '5000'))
    if not 1 <= _puerto <= 65535:
        raise ValueError('PORT debe estar entre 1 y 65535.')
    print('[Casa Pepe] Base de datos inicializada.', flush=True)
    print('[Casa Pepe] Registro de errores: ' + str(_LOG_FILE), flush=True)
    print('[Casa Pepe] Abre el navegador: http://127.0.0.1:' + str(_puerto) + '/', flush=True)
    print('[Casa Pepe] Diagnóstico: http://127.0.0.1:' + str(_puerto) + '/readyz', flush=True)
    print('[Casa Pepe] Mantén esta ejecución abierta mientras usas la web.', flush=True)
    if IS_PRODUCTION:
        try:
            from waitress import serve
        except ImportError as exc:
            raise RuntimeError('Instala waitress para ejecutar en producción.') from exc
        serve(app, host='0.0.0.0', port=_puerto,
              threads=max(2, min(16, int(os.environ.get('CASAPEPE_THREADS', '4')))))
    else:
        app.run(host='127.0.0.1', port=_puerto, debug=False,
                use_reloader=False, threaded=True)
